$anchor$;
  v_hash      text;
  v_cnt       integer;
  v_added     integer;
  v_altered   integer;
  v_gone      integer;
  v_classified integer;
  v_rx        text := $rx$(insert\s+into|update|merge\s+into|copy)\s+(only\s+)?("?public"?\.)?"?study_sessions"?([^a-z0-9_]|$)$rx$;
BEGIN
  -- ---- 2. identity
  SELECT string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod), ',' ORDER BY a.attnum) INTO v
    FROM pg_attribute a WHERE a.attrelid = v_rel AND a.attnum > 0 AND NOT a.attisdropped;
  IF v IS DISTINCT FROM $lit$id:uuid,user_id:uuid,started_at:timestamp with time zone,ended_at:timestamp with time zone,duration_seconds:integer,session_date:date,source:text,created_at:timestamp with time zone,category:text,session_id:uuid,classification:text,discipline_id:uuid,subject_id:uuid,custom_course_label:text,custom_course_key:text,custom_subject_label:text,custom_subject_key:text$lit$ THEN RAISE EXCEPTION 'B-04b stopped: study_sessions columns differ from the frozen 17. Live: %', v; END IF;

  SELECT count(*) INTO n FROM pg_constraint WHERE conrelid = v_rel AND NOT convalidated
     AND conname IN ('study_sessions_discipline_id_fkey', 'study_sessions_discipline_subject_fkey', 'study_sessions_classification_values', 'study_sessions_classification_shape', 'study_sessions_machine_source_unclassified');
  IF n <> 5 THEN RAISE EXCEPTION 'B-04b stopped: the five B-04a constraints are not all present and NOT VALID (found %)', n; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = v_rel AND conname = 'study_sessions_source_check' AND convalidated) THEN
    RAISE EXCEPTION 'B-04b stopped: study_sessions_source_check is missing or not validated';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = v_rel AND conname = 'study_sessions_manual_requires_classification') THEN
    RAISE EXCEPTION 'B-04b stopped: study_sessions_manual_requires_classification already exists';
  END IF;

  -- ---- 3. closure (zero sinks)
  SELECT string_agg(r.rolname, ',' ORDER BY r.rolname) INTO v FROM pg_roles r
   WHERE NOT r.rolsuper AND r.oid <> (SELECT relowner FROM pg_class WHERE oid = v_rel) AND has_any_column_privilege(r.oid, v_rel, 'UPDATE');
  IF v IS NOT NULL THEN RAISE EXCEPTION 'B-04b stopped: roles holding UPDATE on study_sessions: %', v; END IF;

  SELECT (SELECT count(*) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) x WHERE c.oid = v_rel AND x.grantee = 0 AND x.privilege_type IN ('UPDATE', 'INSERT'))
       + (SELECT count(*) FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid = v_rel AND a.attacl IS NOT NULL AND x.grantee = 0 AND x.privilege_type IN ('UPDATE', 'INSERT')) INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'B-04b stopped: PUBLIC holds INSERT or UPDATE on study_sessions (% grants)', n; END IF;

  IF has_table_privilege('anon', v_rel, 'INSERT') OR has_table_privilege('service_role', v_rel, 'INSERT') OR NOT has_table_privilege('authenticated', v_rel, 'INSERT') THEN
    RAISE EXCEPTION 'B-04b stopped: INSERT privilege on study_sessions is not exactly authenticated only (among anon, service_role, authenticated)';
  END IF;

  SELECT string_agg(t.tgname || ':' || t.tgenabled::text, ',' ORDER BY t.tgname) INTO v FROM pg_trigger t WHERE t.tgrelid = v_rel AND NOT t.tgisinternal;
  IF v IS DISTINCT FROM 'trg_study_sessions_label_guard:O' THEN RAISE EXCEPTION 'B-04b stopped: triggers on study_sessions differ. Live: %', v; END IF;

  SELECT count(*) INTO n FROM pg_rewrite w WHERE w.ev_class = v_rel;
  IF n <> 0 THEN RAISE EXCEPTION 'B-04b stopped: % rewrite rule(s) on study_sessions', n; END IF;

  SELECT string_agg(vw.oid::regclass::text, ',' ORDER BY vw.oid::regclass::text) INTO v
    FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid AND d.classid = 'pg_rewrite'::regclass
    JOIN pg_class vw ON vw.oid = w.ev_class
   WHERE d.refobjid = v_rel AND vw.oid <> v_rel AND vw.relkind IN ('v', 'm') AND (pg_relation_is_updatable(vw.oid, false) & 12) <> 0;
  IF v IS NOT NULL THEN RAISE EXCEPTION 'B-04b stopped: insertable or updatable view(s) over study_sessions: %', v; END IF;

  SELECT string_agg(c.conname, ',' ORDER BY c.conname) INTO v FROM pg_constraint c
   WHERE c.conrelid = v_rel AND c.contype = 'f' AND (c.confdeltype IN ('n', 'd') OR c.confupdtype IN ('n', 'd'));
  IF v IS NOT NULL THEN RAISE EXCEPTION 'B-04b stopped: foreign key(s) of study_sessions with SET NULL or SET DEFAULT: %', v; END IF;

  SELECT string_agg(ns.nspname || '.' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')', ',' ORDER BY ns.nspname, p.proname) INTO v
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
   WHERE ns.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind IN ('f', 'p') AND p.prosrc ~* v_rx;
  IF v IS NOT NULL THEN RAISE EXCEPTION 'B-04b stopped: routine(s) with a write statement on study_sessions: %', v; END IF;

  IF to_regclass('cron.job') IS NULL THEN RAISE EXCEPTION 'B-04b stopped: cron.job is not visible, so scheduled jobs cannot be asserted'; END IF;
  EXECUTE 'SELECT count(*) FROM cron.job WHERE command ~* $1' INTO n USING v_rx;
  IF n <> 0 THEN RAISE EXCEPTION 'B-04b stopped: % scheduled job(s) with a write statement on study_sessions', n; END IF;

  -- ---- 4. set assertion SA
  SELECT encode(sha256(convert_to(COALESCE(string_agg(q.id || ':' || q.fp, ',' ORDER BY q.id COLLATE "C"), ''), 'UTF8')), 'hex'), count(*) INTO v_hash, v_cnt
    FROM (SELECT split_part(l, '|', 1) AS id, split_part(l, '|', 2) AS fp FROM regexp_split_to_table(v_anchor, '[\r\n]+') AS l WHERE l <> '') q;
  IF v_hash IS DISTINCT FROM '86353cb4c83ab5a8870ba5e072843b6dcd695787b57b353d9b5457d5f85acb87' OR v_cnt <> 1411 THEN
    RAISE EXCEPTION 'B-04b stopped: the embedded anchor is not the S0 anchor (count %, hash %)', v_cnt, v_hash;
  END IF;

  WITH a AS (SELECT split_part(l, '|', 1) AS id, split_part(l, '|', 2) AS fp FROM regexp_split_to_table(v_anchor, '[\r\n]+') AS l WHERE l <> ''),
       c AS (SELECT s.id::text AS id, encode(sha256(convert_to((SELECT string_agg(CASE WHEN u.v IS NULL THEN 'N' ELSE 'V' || length(u.v)::text || ':' || u.v END, '|' ORDER BY u.ord) FROM unnest(ARRAY[s.id::text, s.user_id::text, s.started_at::text, s.ended_at::text, s.duration_seconds::text, s.session_date::text, s.source::text, s.created_at::text, s.category::text, s.session_id::text, s.classification::text, s.discipline_id::text, s.subject_id::text, s.custom_course_label::text, s.custom_course_key::text, s.custom_subject_label::text, s.custom_subject_key::text]) WITH ORDINALITY AS u(v, ord)), 'UTF8')), 'hex') AS fp FROM public.study_sessions s WHERE s.source = 'manual' AND s.classification IS NULL)
  SELECT (SELECT count(*) FROM c WHERE NOT EXISTS (SELECT 1 FROM a WHERE a.id = c.id)),
         (SELECT count(*) FROM c JOIN a ON a.id = c.id WHERE c.fp <> a.fp),
         (SELECT count(*) FROM a WHERE NOT EXISTS (SELECT 1 FROM public.study_sessions s WHERE s.id::text = a.id)),
         (SELECT count(*) FROM a WHERE EXISTS (SELECT 1 FROM public.study_sessions s WHERE s.id::text = a.id) AND NOT EXISTS (SELECT 1 FROM c WHERE c.id = a.id))
    INTO v_added, v_altered, v_gone, v_classified;
  IF v_added <> 0 OR v_altered <> 0 THEN
    RAISE EXCEPTION 'B-04b stopped by SA: % manual row(s) without a classification are not in the anchor, % anchor row(s) were altered (gone %, classified %)', v_added, v_altered, v_gone, v_classified;
  END IF;
  RAISE NOTICE 'SA holds: added 0, altered 0, gone %, classified %', v_gone, v_classified;
END
$b04b$;

-- ---- 5. the rule
ALTER TABLE public.study_sessions
  ADD CONSTRAINT study_sessions_manual_requires_classification CHECK (source <> 'manual' OR classification IS NOT NULL) NOT VALID;

-- ---- 6. post-check and the one read-only result row
DO $post$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.study_sessions'::regclass AND conname = 'study_sessions_manual_requires_classification' AND contype = 'c' AND NOT convalidated
                    AND pg_get_constraintdef(oid) LIKE '%classification IS NOT NULL%NOT VALID') THEN
    RAISE EXCEPTION 'B-04b stopped: the constraint is not present as built';
  END IF;
END
$post$;

WITH c AS (SELECT s.id::text AS id, s.duration_seconds, encode(sha256(convert_to((SELECT string_agg(CASE WHEN u.v IS NULL THEN 'N' ELSE 'V' || length(u.v)::text || ':' || u.v END, '|' ORDER BY u.ord) FROM unnest(ARRAY[s.id::text, s.user_id::text, s.started_at::text, s.ended_at::text, s.duration_seconds::text, s.session_date::text, s.source::text, s.created_at::text, s.category::text, s.session_id::text, s.classification::text, s.discipline_id::text, s.subject_id::text, s.custom_course_label::text, s.custom_course_key::text, s.custom_subject_label::text, s.custom_subject_key::text]) WITH ORDINALITY AS u(v, ord)), 'UTF8')), 'hex') AS fp FROM public.study_sessions s WHERE s.source = 'manual' AND s.classification IS NULL)
SELECT jsonb_build_object(
  'tool_version', 'B04b-v1',
  'finished_utc', to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'constraint_added', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.study_sessions'::regclass AND conname = 'study_sessions_manual_requires_classification'),
  'constraint_validated', (SELECT convalidated FROM pg_constraint WHERE conrelid = 'public.study_sessions'::regclass AND conname = 'study_sessions_manual_requires_classification'),
  'constraint_def', (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.study_sessions'::regclass AND conname = 'study_sessions_manual_requires_classification'),
  'legacy_set_count', (SELECT count(*) FROM c),
  'legacy_set_sum_duration_seconds', (SELECT COALESCE(sum(duration_seconds), 0) FROM c),
  'legacy_set_overall_hash', (SELECT encode(sha256(convert_to(COALESCE(string_agg(c.id || ':' || c.fp, ',' ORDER BY c.id COLLATE "C"), ''), 'UTF8')), 'hex') FROM c),
  'anchor_overall_hash', '86353cb4c83ab5a8870ba5e072843b6dcd695787b57b353d9b5457d5f85acb87',
  'study_sessions_total', (SELECT count(*) FROM public.study_sessions)
) AS result;
